<span class="line"><span style="color:#E06C75;font-style:italic;">        default_diagnoses</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">[</span><span style="color:#98C379;">&quot;社区获得性肺炎&quot;</span><span style="color:#ABB2BF;">],</span></span>
